void s321_opt(int iterations, int LEN_1D, float* a, float* b) {
    for (int nl = 0; nl < iterations; nl++) {
        float prev = a[0];
        for (int i = 1; i < LEN_1D; i++) {
            float temp = a[i];
            a[i] = temp + prev * b[i];
            prev = a[i];
        }
    }
}

typedef float float4 __attribute__((ext_vector_type(4)));

void vectorized_s321(int iterations, int LEN_1D, float* a, float* b) {
    for (int nl = 0; nl < iterations; nl++) {
        float prev = a[0];

        // Process first element separately to establish prev
        int i = 1;

        // Main vectorized loop - handles recurrence explicitly
        for (; i + 3 < LEN_1D; i += 4) {
            // Load current block of a and b
            float4 a_vec = {a[i], a[i+1], a[i+2], a[i+3]};
            float4 b_vec = {b[i], b[i+1], b[i+2], b[i+3]};

            // Sequential scan across the 4 lanes
            float result[4];

            // Lane 0
            result[0] = a_vec[0] + prev * b_vec[0];

            // Lane 1
            result[1] = a_vec[1] + result[0] * b_vec[1];

            // Lane 2
            result[2] = a_vec[2] + result[1] * b_vec[2];

            // Lane 3
            result[3] = a_vec[3] + result[2] * b_vec[3];

            // Store results
            a[i] = result[0];
            a[i+1] = result[1];
            a[i+2] = result[2];
            a[i+3] = result[3];

            // Update prev for next iteration
            prev = result[3];
        }

        // Scalar cleanup tail
        for (; i < LEN_1D; i++) {
            float temp = a[i];
            a[i] = temp + prev * b[i];
            prev = a[i];
        }
    }
}
